  (md5('malek-demo:demo-product-iphone-18-pro')::uuid, 'iphone-18-pro', md5('malek-demo:demo-brand-apple')::uuid, 'iPhone 18 Pro', '{"ar":"iPhone 18 Pro","en":"iPhone 18 Pro"}'::jsonb, '{"ar":"الجديد من Apple — متاح بكل المساحات","en":"New from Apple — available in every storage"}'::jsonb, '{"ar":"iPhone 18 Pro متاح الآن في MALEK STORE. اختار المساحة واللون المناسبين ليك، وفريقنا يتابع معاك بعد الشراء. التفاصيل الفنية الكاملة يتم تأكيدها عند الإطلاق.","en":"iPhone 18 Pro is available now at MALEK STORE. Choose the storage and colour that suit you, and our team follows up with you after purchase. Full technical details are confirmed at launch."}'::jsonb, '{"ar":"ضمان وكيل","en":"Authorized distributor warranty"}'::jsonb, 'available', 'published', true, true, ((now() - interval '12 days'))::date, 'ايفون آيفون ابل', null, null, now(), true),
