insert into public.content_entries (id, slug, type, eyebrow, title, subtitle, excerpt, body, media_kind, media_url, media_alt, cta_label, cta_href, secondary_cta_label, secondary_cta_href, state, release_date, publish_at, expires_at, is_featured, status, is_demo) values
  (md5('malek-demo:demo-entry-iphone-18-pro-launch')::uuid, 'iphone-18-pro-launch', 'campaign', '{"ar":"جديد في MALEK STORE","en":"New at MALEK STORE"}'::jsonb, '{"ar":"iPhone 18 Pro و iPhone 18 Pro Max","en":"iPhone 18 Pro & iPhone 18 Pro Max"}'::jsonb, '{"ar":"وصلوا عندنا. اختار المساحة واللون اللي يناسبك واطلب من الفرع أو أونلاين قريب.","en":"They have arrived. Pick your storage and colour — order in store now, online soon."}'::jsonb, null, null, 'image', '/demo/media/phone-back-orange.svg', '{"ar":"صورة توضيحية لـ iPhone 18 Pro","en":"Illustration of iPhone 18 Pro"}'::jsonb, '{"ar":"اتسوّق دلوقتي","en":"Shop now"}'::jsonb, '/product/iphone-18-pro', '{"ar":"شوف التفاصيل","en":"View details"}'::jsonb, '/product/iphone-18-pro-max', 'available', null, (now() - interval '12 days'), null, true, 'published', true),
  (md5('malek-demo:demo-entry-iphone-duo-teaser')::uuid, 'iphone-duo-teaser', 'coming_soon', '{"ar":"قريبًا","en":"Coming soon"}'::jsonb, '{"ar":"iPhone Duo","en":"iPhone Duo"}'::jsonb, '{"ar":"حاجة جديدة جاية. سجّل اهتمامك وهنبلغك أول ما يوصل.","en":"Something new is coming. Register your interest and we will tell you first."}'::jsonb, null, null, 'image', '/demo/media/phone-front-black.svg', '{"ar":"صورة تشويقية لـ iPhone Duo","en":"Teaser illustration for iPhone Duo"}'::jsonb, '{"ar":"انضم لقائمة الانتظار","en":"Join the waitlist"}'::jsonb, '/product/iphone-duo', null, null, 'coming_soon', null, (now() - interval '4 days'), null, true, 'published', true),
  (md5('malek-demo:demo-entry-new-iphone-18-pro-release')::uuid, 'new-iphone-18-pro-release', 'new_release', null, '{"ar":"نزل iPhone 18 Pro","en":"iPhone 18 Pro is here"}'::jsonb, '{"ar":"متاح بكل المساحات في الفرع","en":"Available in every storage in store"}'::jsonb, '{"ar":"iPhone 18 Pro و Pro Max متاحين دلوقتي في MALEK STORE.","en":"iPhone 18 Pro and Pro Max are now available at MALEK STORE."}'::jsonb, '{"ar":"iPhone 18 Pro و iPhone 18 Pro Max متاحين دلوقتي في الفرع.\n\nتقدر تختار المساحة واللون، وفريقنا يساعدك في نقل بياناتك وضبط الجهاز.","en":"iPhone 18 Pro and iPhone 18 Pro Max are now available in store.\n\nPick your storage and colour, and our team will help you move your data and set up the phone."}'::jsonb, 'image', '/demo/media/phone-back-silver.svg', '{"ar":"صورة توضيحية","en":"Illustration"}'::jsonb, '{"ar":"اختار جهازك","en":"Choose yours"}'::jsonb, '/product/iphone-18-pro', null, null, 'available', ((now() - interval '12 days'))::date, (now() - interval '12 days'), null, true, 'published', true),
  (md5('malek-demo:demo-entry-new-galaxy-tab-s11')::uuid, 'new-galaxy-tab-s11', 'new_release', null, '{"ar":"Galaxy Tab S11 وصل","en":"Galaxy Tab S11 has arrived"}'::jsonb, null, '{"ar":"تابلت سامسونج الجديد متاح في المتجر.","en":"Samsung’s new tablet is in store."}'::jsonb, null, 'image', '/demo/media/tablet-front-gray.svg', '{"ar":"صورة توضيحية","en":"Illustration"}'::jsonb, '{"ar":"شوف المنتج","en":"View product"}'::jsonb, '/product/galaxy-tab-s11', null, null, 'available', ((now() - interval '30 days'))::date, (now() - interval '30 days'), null, false, 'published', true),
  (md5('malek-demo:demo-entry-accessories-price-update')::uuid, 'accessories-price-update', 'offer_update', null, '{"ar":"أسعار جديدة على الإكسسوارات","en":"New prices on accessories"}'::jsonb, null, '{"ar":"جرابات وكابلات وشواحن بأسعار أقل لفترة محدودة (بيانات تجريبية).","en":"Cases, cables and chargers for less, for a limited time (demo content)."}'::jsonb, null, 'image', '/demo/media/case-white.svg', '{"ar":"صورة توضيحية","en":"Illustration"}'::jsonb, '{"ar":"شوف العروض","en":"See offers"}'::jsonb, '/offers', null, null, null, null, (now() - interval '4 days'), null, true, 'published', true),
  (md5('malek-demo:demo-entry-trade-in-at-malek')::uuid, 'trade-in-at-malek', 'news', null, '{"ar":"بدّل جهازك القديم في الفرع","en":"Trade in your old device in store"}'::jsonb, '{"ar":"خبر تجريبي","en":"Demo news item"}'::jsonb, '{"ar":"هات جهازك القديم وفريقنا يقيّمه ويحسبلك الفرق على الجديد.","en":"Bring your old device — our team will value it and work out the difference on a new one."}'::jsonb, '{"ar":"خدمة الاستبدال متاحة في فرع العباسية.\n\nالتقييم النهائي بيكون بعد فحص الجهاز في الفرع.","en":"Trade-in is available at the Abbasseya branch.\n\nThe final valuation is confirmed after the device is inspected in store."}'::jsonb, 'image', '/demo/media/phone-front-blue.svg', '{"ar":"صورة توضيحية","en":"Illustration"}'::jsonb, '{"ar":"اعرف أكتر","en":"Learn more"}'::jsonb, '/trade-in', null, null, null, null, (now() - interval '8 days'), null, true, 'published', true),
  (md5('malek-demo:demo-entry-repairs-consultation')::uuid, 'repairs-consultation', 'news', null, '{"ar":"استشارة صيانة قبل أي تصليح","en":"A repair consultation before any fix"}'::jsonb, '{"ar":"خبر تجريبي","en":"Demo news item"}'::jsonb, '{"ar":"بنشخّص المشكلة الأول ونقولك التكلفة المتوقعة قبل ما نبدأ.","en":"We diagnose first and share the expected cost before we start."}'::jsonb, null, 'image', '/demo/media/phone-back-dual-green.svg', '{"ar":"صورة توضيحية","en":"Illustration"}'::jsonb, '{"ar":"اعرف أكتر","en":"Learn more"}'::jsonb, '/repairs', null, null, null, null, (now() - interval '15 days'), null, false, 'published', true)
